update known_safe_harbors set tissue_context = 'HEK293 cells' where source_pmid = '32470292' and evidence_summary = 'Direct comparison of 3 loci in HEK293 cells: of AAVS1, CCR5, and human ROSA26 tested for eGFP expression, AAVS1 had the highest and most homogeneous expression of the three. Expression at AAVS1 sustained ~3 months without selection. Within AAVS1 itself, promoter ranking: CMV > EF1a > SV40 > TK.';
