update known_safe_harbors set tissue_context = 'Cell type not specified for the locus itself; effect detected via teratoma assay in vivo (both cell-type-agnostic and in vivo components)' where source_pmid = '30887735' and evidence_summary = 'Extragenic candidate locus on chromosome 1. Important cautionary finding: the locus itself allowed robust transgene expression, BUT a gene 2Mb away, within the same topologically associated domain (TAD), showed aberrant expression -- despite the distance, 3D TAD organization propagated the effect. The authors conclude Chr1-eGSH is not suitable for therapeutic gene integration despite the locus itself appearing good. Also tested with a suicide-gene safety system (HSV-TK/ganciclovir): sensitive in vitro, but resulting teratomas showed variable degrees of resistance in vivo -- the safety system itself is not reliably guaranteed.';
update public_safe_harbors_staging set tissue_context = 'Cell type not specified for the locus itself; effect detected via teratoma assay in vivo (both cell-type-agnostic and in vivo components)' where source_pmid = '30887735' and evidence_summary = 'Extragenic candidate locus on chromosome 1. Important cautionary finding: the locus itself allowed robust transgene expression, BUT a gene 2Mb away, within the same topologically associated domain (TAD), showed aberrant expression -- despite the distance, 3D TAD organization propagated the effect. The authors conclude Chr1-eGSH is not suitable for therapeutic gene integration despite the locus itself appearing good. Also tested with a suicide-gene safety system (HSV-TK/ganciclovir): sensitive in vitro, but resulting teratomas showed variable degrees of resistance in vivo -- the safety system itself is not reliably guaranteed.';

