update known_safe_harbors set tissue_context = 'Transformed and primary cells (fibroblasts, hES)' where source_pmid = '20508142' and evidence_summary = 'Founding paper (2010): ZFN targets PPP1R12C (AAVS1) without drug selection, transgenesis efficiency up to 15% in transient transfection, in transformed AND primary cells (fibroblasts, hES). Transgenes (shRNA, small-molecule-responsive cassettes, reporters) show consistent expression and sustained function for over 50 cell generations -- classic reference for "AAVS1 holds up over many generations".';
