update known_safe_harbors set tissue_context = 'Human CD34+ HSPCs; neutrophils ex vivo; bone marrow in vivo (transplanted mice)' where source_pmid = '26950749' and evidence_summary = 'Targeted integration in human CD34+ HSPCs: up to 58% Venus+ cells with 6-16% human cell engraftment marking in mice. In HSPCs from X-linked chronic granulomatous disease patients, gp91phox transgene at AAVS1 gave ~15% expression and increased NADPH oxidase activity in neutrophils ex vivo; in transplanted mice, 4-11% of human cells in bone marrow expressed gp91phox -- moderate but carefully quantified efficiency.';
